<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Support\{Pagination,Request,Response};
final class AdminCompanyController extends Controller {
    public function index(Request $r):Response{$page=max(1,(int)$r->input('page',1));$data=app('companies')->repo()->adminList(['q'=>$r->input('q',''),'status'=>$r->input('status',''),'country'=>$r->input('country','')],new Pagination($page,25,0));return $this->view('admin.companies',['title'=>'Companies','companies'=>$data['items'],'pagination'=>new Pagination($page,25,$data['total']),'countries'=>app('countries')->all(),'filters'=>$r->all()],'layouts.admin');}
    public function create(Request $r):Response{return $this->editor(null);}
    public function edit(Request $r):Response{$company=app('companies')->repo()->byId((int)$r->route('company'));if(!$company)throw new \App\Exceptions\NotFoundException('Company not found.');return $this->editor($company);}
    public function store(Request $r):Response{return $this->persist($r,null);}
    public function update(Request $r):Response{return $this->persist($r,(int)$r->route('company'));}
    public function archive(Request $r):Response{$id=(int)$r->route('company');$archive=(string)$r->input('action')==='archive';$old=app('companies')->repo()->byId($id);if(!$old)throw new \App\Exceptions\NotFoundException('Company not found.');app('companies')->repo()->archive($id,$archive);app('audit')->record((int)$_SESSION['user_id'],$archive?'company.archived':'company.restored','company',$id,['status'=>$old['status']],['status'=>$archive?'ARCHIVED':'ACTIVE'],null,$r);$this->flash('success',$archive?'Company archived.':'Company restored.');return $this->redirect('admin.companies.index');}
    private function editor(?array $company):Response{return $this->view('admin.company-edit',['title'=>$company?'Edit company':'Create company','company'=>$company??['status'=>'DRAFT','currency_code'=>country()->currencyCode(),'profit_type'=>'PERCENTAGE','duration_unit'=>'DAYS','quantity_decimal_places'=>0,'fractional_shares_allowed'=>0,'selling_enabled'=>0,'offering_active'=>0,'offering_featured'=>0],'countries'=>app('countries')->all(),'images'=>$company?app('companies')->repo()->images((int)$company['id']):[],'sources'=>$company?app('companies')->repo()->sources((int)$company['id']):[]],'layouts.admin');}
    private function persist(Request $r,?int $id):Response{$input=$r->all();$errors=app('offering_validator')->validate($input);foreach(['legal_name','display_name','slug','ticker','stock_exchange','country_id']as$f)if(trim((string)($input[$f]??''))==='')$errors[$f]='This field is required.';if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',(string)($input['slug']??'')))$errors['slug']='Use a lowercase URL slug.';foreach(['website_url','investor_relations_url']as$f)if(($input[$f]??'')!==''&&!filter_var($input[$f],FILTER_VALIDATE_URL))$errors[$f]='Enter a valid URL.';if($errors){$_SESSION['_errors']=$errors;$_SESSION['_old']=$input;return $id?$this->redirect('admin.companies.edit',['company'=>$id]):$this->redirect('admin.companies.create');}$scale=in_array($input['currency_code'],['JPY','KRW'],true)?0:2;try{$price=\App\Support\Money::parse((string)$input['share_price'],(string)$input['currency_code'],$scale)->minor;}catch(\Throwable){$_SESSION['_errors']=['share_price'=>'Invalid investment price.'];return $this->redirect($id?'admin.companies.edit':'admin.companies.create',$id?['company'=>$id]:[]);} $company=['legal_name'=>trim($input['legal_name']),'display_name'=>trim($input['display_name']),'slug'=>trim($input['slug']),'ticker'=>trim($input['ticker']),'stock_exchange'=>trim($input['stock_exchange']),'exchange_mic'=>trim($input['exchange_mic']??''),'isin'=>trim($input['isin']??''),'listing_country_code'=>strtoupper(trim($input['listing_country_code']??'')),'headquarters_country_code'=>strtoupper(trim($input['headquarters_country_code']??'')),'headquarters_city'=>trim($input['headquarters_city']??''),'sector'=>trim($input['sector']??''),'industry'=>trim($input['industry']??''),'year_founded'=>trim($input['year_founded']??''),'website_url'=>trim($input['website_url']??''),'investor_relations_url'=>trim($input['investor_relations_url']??''),'short_description'=>trim($input['short_description']??''),'long_profile'=>trim($input['long_profile']??''),'status'=>$input['status'],'is_featured'=>isset($input['is_featured'])?1:0,'sort_order'=>(int)($input['sort_order']??0),'last_verified_at'=>trim($input['last_verified_at']??'')];$offering=['country_id'=>(int)$input['country_id'],'currency_code'=>$input['currency_code'],'share_price_minor'=>$price,'minimum_purchase_quantity'=>$input['minimum_purchase_quantity'],'maximum_purchase_quantity'=>$input['maximum_purchase_quantity']?:null,'maximum_user_holding'=>$input['maximum_user_holding']?:null,'total_available_quantity'=>$input['total_available_quantity']?:null,'fractional_shares_allowed'=>isset($input['fractional_shares_allowed'])?1:0,'quantity_decimal_places'=>(int)$input['quantity_decimal_places'],'profit_type'=>$input['profit_type'],'projected_profit_value'=>$input['projected_profit_value'],'fixed_profit_basis'=>$input['profit_type']==='FIXED'?$input['fixed_profit_basis']:null,'duration_value'=>(int)$input['duration_value'],'duration_unit'=>$input['duration_unit'],'selling_enabled'=>isset($input['selling_enabled'])?1:0,'is_active'=>isset($input['offering_active'])?1:0,'is_featured'=>isset($input['offering_featured'])?1:0,'available_from'=>null,'available_until'=>null,'change_reason'=>trim($input['change_reason']??'')];$old=$id?app('companies')->repo()->byId($id):null;$saved=app('companies')->repo()->save($company,$offering,$id);app('audit')->record((int)$_SESSION['user_id'],$id?'company.updated':'company.created','company',$saved,$old?$old:null,['company'=>$company,'offering'=>$offering],$offering['change_reason']?:null,$r);$this->flash('success',$id?'Company and offering saved.':'Company and offering created.');return $this->redirect('admin.companies.edit',['company'=>$saved]);}
}
